mapper.select:
SELECT * FROM attendance_session WHERE course_id IN
#{courseId}
ORDER BY start_time DESC, session_id DESC

mapper.sql:
WHERE c.teacher_id = #{teacherId}
AND a.course_id = #{query.courseId}
AND a.start_time >= CONCAT(#{query.startDate}, ' 00:00:00')
AND a.start_time < DATE_ADD(CONCAT(#{query.endDate}, ' 00:00:00'), INTERVAL 1 DAY)
AND NOT EXISTS ( SELECT 1 FROM attendance_record type_record WHERE type_record.session_id = a.session_id AND type_record.update_type = 2 )
AND EXISTS ( SELECT 1 FROM attendance_record type_record WHERE type_record.session_id = a.session_id AND type_record.update_type = 2 )
AND EXISTS ( SELECT 1 FROM attendance_record filter_record LEFT JOIN student filter_student ON filter_record.student_id = filter_student.user_id LEFT JOIN user filter_user ON filter_record.student_id = filter_user.user_id WHERE filter_record.session_id = a.session_id
AND filter_student.admin_class = #{query.adminClass}
AND filter_record.status = #{query.status}
AND ( filter_student.student_number LIKE CONCAT('%', #{query.keyword}, '%') OR filter_user.real_name LIKE CONCAT('%', #{query.keyword}, '%') )
)

mapper.select:
SELECT a.session_id AS id, c.course_name AS courseName, COALESCE( NULLIF(GROUP_CONCAT(DISTINCT NULLIF(stu.admin_class, '') ORDER BY stu.admin_class SEPARATOR ' / '), ''), '未分班' ) AS className, DATE_FORMAT(a.start_time, '%Y-%m-%d %H:%i:%s') AS sessionTime, IFNULL(a.total_student, COUNT(ar.record_id)) AS expectedCount, SUM(CASE WHEN ar.status IN (1, 2) THEN 1 ELSE 0 END) AS actualCount, SUM(CASE WHEN ar.status = 0 THEN 1 ELSE 0 END) AS absentCount, SUM(CASE WHEN ar.status = 2 THEN 1 ELSE 0 END) AS lateCount, SUM(CASE WHEN ar.status = 3 THEN 1 ELSE 0 END) AS leaveCount, CONCAT( CAST( ROUND( IFNULL( SUM(CASE WHEN ar.status IN (1, 2) THEN 1 ELSE 0 END) * 100.0 / NULLIF(IFNULL(a.total_student, COUNT(ar.record_id)), 0), 0 ), 1 ) AS CHAR ), '%' ) AS attendanceRate, CASE WHEN MAX(CASE WHEN ar.update_type = 2 THEN 1 ELSE 0 END) = 1 THEN '人工修正' ELSE '课堂识别' END AS type FROM attendance_session a INNER JOIN course c ON a.course_id = c.course_id LEFT JOIN attendance_record ar ON a.session_id = ar.session_id LEFT JOIN student stu ON ar.student_id = stu.user_id WHERE a.session_id IN
#{sessionId}
GROUP BY a.session_id, c.course_name, a.start_time, a.total_student

mapper.update:
UPDATE attendance_session
source_images = #{sourceImages}, total_student = #{totalStudent}, actual_student = #{actualStudent},
WHERE session_id = #{sessionId}
